        6 => SKILLS_WORKSPACE_TRANSPORT_TLS_FAILURE,
        7 => SKILLS_WORKSPACE_TRANSPORT_NETWORK_FAILURE,
        8 => SKILLS_WORKSPACE_TRANSPORT_TIMED_OUT,
        9 => SKILLS_WORKSPACE_TRANSPORT_REF_NOT_FOUND,
        10 => SKILLS_WORKSPACE_TRANSPORT_REPOSITORY_FAILURE,
        11 => SKILLS_WORKSPACE_TRANSPORT_OBJECT_FAILURE,
        12 => SKILLS_WORKSPACE_TRANSPORT_BUFFER_TOO_SMALL,
        13 => SKILLS_WORKSPACE_TRANSPORT_LIMIT_EXCEEDED,
        14 => SKILLS_WORKSPACE_TRANSPORT_UNSUPPORTED,
        _ => throw ArgumentError(
          'Unknown value for skills_workspace_transport_status: $value',
        ),
      };
}
